def test_hyb_mgga_xc_tpss1kcis_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_mgga_xc_tpss1kcis", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.152915806659490e+00, -4.069455365235910e+00, -3.952462400003653e+00, -3.790310134223596e+00, -3.569192874932390e+00, -3.274634562068718e+00, -2.895257471003164e+00, -2.430303258255467e+00, -1.903048756141702e+00, -1.377984666760764e+00, -9.221114003588144e-01, -6.436339554101103e-01, -5.646757063980457e-01, -4.712681533276429e-01, -3.350464308269084e-01, -2.085164981023637e-01, -1.161005003500317e-01, -4.327379051127316e-02, -9.410322168593320e-03, -1.058109461772337e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


